seq = open('region.fasta').read().split('\n',1)[1].replace('\n','').strip()
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
# approximate inverted repeats via DP: D[a][b] = 1 + D[a-1][b+1] if seq[a]==comp(seq[b])
import numpy as np
D=[[0]*(n+1) for _ in range(n+1)]
best=[]
for a in range(n):
    for b in range(n-1,-1,-1):
        if seq[a]==comp[seq[b]]:
            D[a][b]=1+D[a-1][b+1] if (a-1>=0 and b+1<=n-1) else 1
# report longest runs where the arms do not overlap much
cands=[]
for a in range(n):
    for b in range(n):
        L=D[a][b]
        if L>=14:
            left_start=a-L+1
            right_end=b
            cands.append((L,left_start,right_end))
cands.sort(key=lambda x:-x[0])
seen=[]
for L,ls,re in cands:
    if all(not(ls<=s and e<=re) for s,e in seen):
        seen.append((ls,re))
        print(L, ls, re, seq[ls:ls+L], seq[re-L+1:re+1])
        if len(seen)>25: break
